import{az as e,P as s,Q as a,aQ as n}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const b=JSON.parse('{"title":"BiyaPay 交易平台 - 项目经验详述","description":"","frontmatter":{},"headers":[],"relativePath":"其他/PROJECT_RESUME.md","filePath":"其他/PROJECT_RESUME.md","lastUpdated":1781716938000}'),d={name:"其他/PROJECT_RESUME.md"};function o(i,t,l,r,p,c){return s(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="biyapay-交易平台-项目经验详述" tabindex="-1">BiyaPay 交易平台 - 项目经验详述 <a class="header-anchor" href="#biyapay-交易平台-项目经验详述" aria-label="Permalink to “BiyaPay 交易平台 - 项目经验详述”">​</a></h1><hr><h2 id="项目概况" tabindex="-1">项目概况 <a class="header-anchor" href="#项目概况" aria-label="Permalink to “项目概况”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>详情</th></tr></thead><tbody><tr><td>项目名称</td><td>BiyaPay 多资产综合交易平台 (invest-biyapay-project)</td></tr><tr><td>项目类型</td><td>金融科技 / 在线交易平台</td></tr><tr><td>用户群体</td><td>全球个人投资者</td></tr><tr><td>项目规模</td><td>100+ 页面，80+ 业务组件，50+ 国际化语言包</td></tr><tr><td>技术框架</td><td>Next.js 13.5.7 (Pages Router / SSR) + React 18</td></tr><tr><td>UI 框架</td><td>Ant Design 5.24.3 + Tailwind CSS 3</td></tr><tr><td>部署方式</td><td>PM2 进程管理，Docker 容器化，多环境部署</td></tr></tbody></table><hr><h2 id="技术架构" tabindex="-1">技术架构 <a class="header-anchor" href="#技术架构" aria-label="Permalink to “技术架构”">​</a></h2><h3 id="整体架构" tabindex="-1">整体架构 <a class="header-anchor" href="#整体架构" aria-label="Permalink to “整体架构”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                   Pages (SSR)                     │</span></span>
<span class="line"><span>│  首页 / 行情 / 交易 / 资产 / 用户中心 / ...       │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│              Components (80+ 组件)               │</span></span>
<span class="line"><span>│  交易面板 / K线图表 / 订单簿 / 资产列表 / ...      │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│    Context (状态管理层)           Hooks (逻辑层)   │</span></span>
<span class="line"><span>│   ThemeCtx / MarketCtx /          useSocket /     │</span></span>
<span class="line"><span>│   AssestCtx / HttpCtx /           useMessage /    │</span></span>
<span class="line"><span>│   RegionCtx / ChatCtx /           useAuth / ...   │</span></span>
<span class="line"><span>│   DemoAccountCtx                                  │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│    Utils (工具层)               Request (请求层)   │</span></span>
<span class="line"><span>│   TV DataFeed / 格式化 /        Axios / 拦截器 /   │</span></span>
<span class="line"><span>│   加密 / 系统检测 / ...          事件总线 / 加密    │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│              WebSocket (双通道)                    │</span></span>
<span class="line"><span>│   行情推送 (Market)  +  资产/订单推送 (Assest)     │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│           Middleware / i18n / Sentry              │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="context-状态管理层" tabindex="-1">Context 状态管理层 <a class="header-anchor" href="#context-状态管理层" aria-label="Permalink to “Context 状态管理层”">​</a></h3><p>应用使用 <strong>React Context</strong> 进行全局状态管理，包含 13 个 Context Provider，在 <code>_app.jsx</code> 中按层级嵌套注入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span>StyleProvider (CSS-in-JS)</span></span>
<span class="line"><span>  └─ MessageProvider (全局消息提示)</span></span>
<span class="line"><span>       └─ MarketWebSocketProvider (行情 WebSocket)</span></span>
<span class="line"><span>            └─ WebSocketAssestsProvider (资产/订单 WebSocket)</span></span>
<span class="line"><span>                 └─ HttpProvider (HTTP 请求 + 用户登录态)</span></span>
<span class="line"><span>                      └─ RegionRestrictionProvider (地区限制)</span></span>
<span class="line"><span>                           └─ ChatProvider (在线客服)</span></span>
<span class="line"><span>                                └─ ThemeProvider (暗黑/浅色主题)</span></span></code></pre></div><p>各 Context 职责：</p><table tabindex="0"><thead><tr><th>Context</th><th>职责</th></tr></thead><tbody><tr><td><code>ThemeContext</code></td><td>暗黑/浅色主题切换，通过 <code>data-theme</code> 属性驱动全局 CSS 变量</td></tr><tr><td><code>MarketWebSocketProvider</code></td><td>行情数据 WebSocket 连接管理，支持订阅/取消订阅模式，含节流、重连、页面可见性检测</td></tr><tr><td><code>WebSocketAssestsProvider</code></td><td>资产变更 + 订单状态推送，区分真实账户/模拟账户（不同 WebSocket 端点）</td></tr><tr><td><code>HttpProvider</code></td><td>用户登录态管理、401 自动处理（Token 刷新）、未读消息计数、网络状态检测</td></tr><tr><td><code>RegionRestrictionProvider</code></td><td>基于 IP 的地区检测（中国 IP 列表 + ISP 运营商判断），控制部分功能可见性</td></tr><tr><td><code>MessageProvider</code></td><td>全局消息通知（基于 Ant Design message API）</td></tr><tr><td><code>ChatProvider</code></td><td>在线客服 SDK 集成</td></tr><tr><td><code>DemoAccount</code></td><td>模拟交易账户状态管理</td></tr><tr><td><code>symbinfoContext</code></td><td>当前交易对详情（价格精度、数量精度等）</td></tr><tr><td><code>symbinfoLastPriceContext</code></td><td>使用 <code>useSyncExternalStore</code> 实现的轻量级最新价订阅</td></tr></tbody></table><hr><h2 id="核心业务模块详述" tabindex="-1">核心业务模块详述 <a class="header-anchor" href="#核心业务模块详述" aria-label="Permalink to “核心业务模块详述”">​</a></h2><h3 id="_1-多资产交易系统" tabindex="-1">1. 多资产交易系统 <a class="header-anchor" href="#_1-多资产交易系统" aria-label="Permalink to “1. 多资产交易系统”">​</a></h3><p>支持 <strong>6 大类</strong> 金融产品的在线交易：</p><table tabindex="0"><thead><tr><th>交易品种</th><th>页面路由</th><th>核心功能</th></tr></thead><tbody><tr><td>加密货币现货</td><td><code>/spot/[id]</code></td><td>限价/市价下单、订单簿、深度图、TradingView K 线</td></tr><tr><td>永续合约</td><td><code>/futures/[id]</code> 或 <code>/perpetual/[id]</code></td><td>杠杆设置、止盈止损、持仓管理、强平价格计算</td></tr><tr><td>美股</td><td><code>/us-stock/[id]</code></td><td>Level 2 行情、盘口深度、OCO 订单（止损限价/止盈限价）</td></tr><tr><td>港股</td><td><code>/hk-stock/[id]</code></td><td>港股实时行情、限价/市价/竞价单</td></tr><tr><td>美股期权</td><td><code>/us-stock-option/[id]</code></td><td>期权链、希腊值展示、行权</td></tr><tr><td>港股期权</td><td><code>/hk-stock-option/[id]</code></td><td>港股期权链、多策略下单</td></tr></tbody></table><h3 id="_2-tradingview-图表集成-自研-datafeed-适配层" tabindex="-1">2. TradingView 图表集成（自研 DataFeed 适配层） <a class="header-anchor" href="#_2-tradingview-图表集成-自研-datafeed-适配层" aria-label="Permalink to “2. TradingView 图表集成（自研 DataFeed 适配层）”">​</a></h3><p>在 <code>lib/</code> 目录下为每种资产类型独立实现了 TradingView DataFeed 接口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span>lib/</span></span>
<span class="line"><span>├── spot/datafeed.js          # 现货 DataFeed</span></span>
<span class="line"><span>├── spot/historyProvider.js    # 历史 K 线数据提供者</span></span>
<span class="line"><span>├── spot/dataPulseProvider.js  # 实时数据脉冲提供者</span></span>
<span class="line"><span>├── futures/                   # 期货 DataFeed（同上结构）</span></span>
<span class="line"><span>├── futures-contract/          # 期货合约 DataFeed</span></span>
<span class="line"><span>├── stock/                     # 股票 DataFeed</span></span>
<span class="line"><span>└── option/                    # 期权 DataFeed</span></span></code></pre></div><p>每个 DataFeed 实现包含：</p><ul><li><strong>HistoryProvider</strong>: 通过 HTTP API 拉取历史 K 线数据，支持 <code>1min / 5min / 15min / 30min / 60min / 4H / 1D / 3D / 1W / 1M / 12M</code> 等全分辨率</li><li><strong>DataPulseProvider</strong>: 将 WebSocket 实时数据脉冲注入 TradingView 图表，实现毫秒级实时更新</li><li><strong>resolveSymbol / getBars / subscribeBars / unsubscribeBars</strong>: 完整实现 TradingView Charting Library 要求的全部接口</li></ul><h3 id="_3-websocket-实时数据系统" tabindex="-1">3. WebSocket 实时数据系统 <a class="header-anchor" href="#_3-websocket-实时数据系统" aria-label="Permalink to “3. WebSocket 实时数据系统”">​</a></h3><p>实现双通道 WebSocket 架构，采用 <strong>发布-订阅模式</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span>行情通道 (MarketWebSocketProvider)</span></span>
<span class="line"><span>  ├── 连接管理: 自动重连（指数退避）、心跳保活、页面不可见自动断开</span></span>
<span class="line"><span>  ├── 订阅机制: 基于 Symbol 唯一 ID 的订阅/取消订阅，支持节流回调</span></span>
<span class="line"><span>  ├── 消息队列: 断线期间缓存消息，重连后批量推送</span></span>
<span class="line"><span>  └── 广播服务: BroadcastChannel API 实现跨 Tab 数据同步</span></span>
<span class="line"><span></span></span>
<span class="line"><span>资产通道 (WebSocketAssestsProvider)</span></span>
<span class="line"><span>  ├── JWT 认证: 拼接 access_token 到 WebSocket URL</span></span>
<span class="line"><span>  ├── 真实/模拟账户: 通过 isDemoAccount 区分配置不同端点</span></span>
<span class="line"><span>  ├── 资产变更推送: 余额、持仓、订单状态实时更新</span></span>
<span class="line"><span>  └── 多 Tab 同步: broadcastService 跨标签页数据共享</span></span></code></pre></div><p>WebSocket 连接具有以下容错机制：</p><ul><li><strong>重连策略</strong>: 指数退避（1s -&gt; 2s -&gt; 4s -&gt; ... -&gt; 30s 上限），最多重试 30 次</li><li><strong>页面可见性</strong>: 页面隐藏超过 5 分钟自动断开 WebSocket 连接，恢复可见时自动重连</li><li><strong>消息节流</strong>: 高频推送消息支持可配置的节流延迟</li><li><strong>Sentry 异常捕获</strong>: 所有 WebSocket 错误通过 <code>captureException</code> 上报</li></ul><h3 id="_4-资产与资金管理" tabindex="-1">4. 资产与资金管理 <a class="header-anchor" href="#_4-资产与资金管理" aria-label="Permalink to “4. 资产与资金管理”">​</a></h3><p><strong>资产总览</strong> (<code>/assets</code>):</p><ul><li>总估值展示、各账户资产分布</li><li>钱包列表管理</li><li>Banner 轮播、跑马灯公告</li></ul><p><strong>转账体系</strong> (<code>/assets/transfer</code>):</p><table tabindex="0"><thead><tr><th>功能</th><th>路由</th><th>说明</th></tr></thead><tbody><tr><td>链上充值</td><td><code>/assets/transfer/in/on-chain-recharge</code></td><td>多网络选择、充值地址生成</td></tr><tr><td>链上提现</td><td><code>/assets/transfer/out/on-chain-withdrawal</code></td><td>地址管理、数量输入、手续费计算、MEMO</td></tr><tr><td>汇款</td><td><code>/assets/transfer/out/remittance</code></td><td>收款人管理、汇款表单、补充材料上传</td></tr><tr><td>邮件收款</td><td><code>/assets/transfer/in/email-receipt</code></td><td>邮箱收款流程</td></tr><tr><td>内部转账</td><td><code>/assets/internal-transfer</code></td><td>站内账户互转</td></tr><tr><td>闪兑</td><td><code>/assets/fast-exchange</code></td><td>即时币币兑换</td></tr><tr><td>账单中心</td><td><code>/assets/bill/*</code></td><td>多类型账单（现货/合约/股票/资金）</td></tr></tbody></table><p><strong>支付账户</strong> (<code>/assets/payment</code>):</p><ul><li>多币种账户创建与管理</li><li>收款账户详情查看</li><li>充值流程与凭证上传</li><li>AML 反洗钱验证</li><li>补充材料提交</li></ul><h3 id="_5-用户认证与安全体系" tabindex="-1">5. 用户认证与安全体系 <a class="header-anchor" href="#_5-用户认证与安全体系" aria-label="Permalink to “5. 用户认证与安全体系”">​</a></h3><p>完整的账户安全体系，包含以下认证流程：</p><table tabindex="0"><thead><tr><th>功能</th><th>页面</th><th>说明</th></tr></thead><tbody><tr><td>登录</td><td><code>/login</code></td><td>邮箱密码登录、验证码登录、二维码登录、多端登录管理</td></tr><tr><td>注册</td><td><code>/register</code></td><td>邮箱注册 + 密码设置</td></tr><tr><td>忘记密码</td><td>登录页内</td><td>邮箱验证码重置</td></tr><tr><td>Google 两步验证</td><td><code>/user/security/google/*</code></td><td>绑定 / 解绑 Google Authenticator</td></tr><tr><td>手机绑定</td><td><code>/user/security/phone/*</code></td><td>手机号绑定 / 换绑</td></tr><tr><td>反钓鱼码</td><td><code>/user/security/phishing-code/*</code></td><td>设置 / 修改反钓鱼码</td></tr><tr><td>密码修改</td><td><code>/user/security/password/reset</code></td><td>密码重置</td></tr><tr><td>验证器管理</td><td><code>/user/security/validator/*</code></td><td>验证器绑定 / 解绑</td></tr><tr><td>设备管理</td><td>设置页</td><td>登录设备列表查看与管理</td></tr></tbody></table><p><strong>KYC 身份认证</strong> 完整流程：</p><ol><li>证件类型选择（身份证 / 护照）</li><li>证件照片上传（支持相机拍照 / 相册选取）</li><li>人脸识别认证（活体检测）</li><li>审核进度查看</li><li>审核驳回 -&gt; 原因查看 + 补充材料重新提交</li></ol><h3 id="_6-行情与资讯模块" tabindex="-1">6. 行情与资讯模块 <a class="header-anchor" href="#_6-行情与资讯模块" aria-label="Permalink to “6. 行情与资讯模块”">​</a></h3><p><strong>行情首页</strong> (<code>/market/crypto/[type]</code>, <code>/market/stocks/[type]</code>, <code>/market/futures/[type]</code>):</p><ul><li>加密货币/股票/期货三大行情 Tab</li><li>涨跌幅排行、成交量排序</li><li>搜索（支持币种/股票名称模糊搜索）</li><li>K 线缩略图预览</li></ul><p><strong>资讯洞察</strong> (<code>/market/insights/[type]</code>):</p><ul><li>AI 行情分析推荐</li><li>热门股票推荐</li><li>财经新闻列表（分类筛选）</li><li>新闻详情页（分享功能）</li></ul><p><strong>自选列表</strong> (<code>/market/watchlist</code>):</p><ul><li>多类型资产统一自选管理</li><li>自选分组</li><li>实时价格刷新</li></ul><p><strong>个股详情页</strong> (<code>/price/[id]</code>):</p><ul><li>实时盘口数据</li><li>K 线图表（TradingView）</li><li>买卖下单面板</li></ul><h3 id="_7-订单与费用系统" tabindex="-1">7. 订单与费用系统 <a class="header-anchor" href="#_7-订单与费用系统" aria-label="Permalink to “7. 订单与费用系统”">​</a></h3><p><strong>订单类型</strong>:</p><ul><li>限价单 / 市价单 / 止损限价单 / 止盈限价单</li><li>OCO 订单（One Cancels Other - 止损限价 + 止盈限价组合）</li><li>条件单（触发价格 + 限价）</li><li>计划委托</li></ul><p><strong>费用中心</strong> (<code>/user/cost</code>):</p><ul><li>交易手续费展示（现货/合约/股票分项）</li><li>融资利率查询</li><li>维持保证金率查询</li><li>资金费率</li></ul><p><strong>账单系统</strong>:</p><ul><li>现货订单历史</li><li>合约/永续合约订单历史</li><li>股票订单历史</li><li>资金流水（充提/转账/汇款/闪兑）</li><li>账单详情 + 推荐引导</li></ul><h3 id="_8-国际化-i18n" tabindex="-1">8. 国际化（i18n） <a class="header-anchor" href="#_8-国际化-i18n" aria-label="Permalink to “8. 国际化（i18n）”">​</a></h3><p>基于 <code>next-i18next</code> 实现，支持 <strong>中文（zh）/ 英文（en）</strong> 双语：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span>public/locales/</span></span>
<span class="line"><span>├── zh/  (中文)</span></span>
<span class="line"><span>│   ├── common.json          # 通用文案</span></span>
<span class="line"><span>│   ├── header.json          # 头部导航</span></span>
<span class="line"><span>│   ├── footer.json          # 页脚</span></span>
<span class="line"><span>│   ├── menu.json            # 菜单</span></span>
<span class="line"><span>│   ├── home.json            # 首页</span></span>
<span class="line"><span>│   ├── assets.json          # 资产</span></span>
<span class="line"><span>│   ├── market.json          # 行情</span></span>
<span class="line"><span>│   ├── order.json           # 订单</span></span>
<span class="line"><span>│   ├── user.json            # 用户中心</span></span>
<span class="line"><span>│   ├── login.json           # 登录</span></span>
<span class="line"><span>│   ├── authentication.json  # 身份认证</span></span>
<span class="line"><span>│   ├── transfers.json       # 转账</span></span>
<span class="line"><span>│   ├── finance.json         # 理财</span></span>
<span class="line"><span>│   ├── help.json            # 帮助</span></span>
<span class="line"><span>│   ├── academy.json         # 学院</span></span>
<span class="line"><span>│   ├── news.json            # 新闻</span></span>
<span class="line"><span>│   ├── feedback.json        # 反馈</span></span>
<span class="line"><span>│   └── ...                  # 其他 20+ 模块</span></span>
<span class="line"><span>└── en/  (英文，同上结构)</span></span></code></pre></div><p>特性：</p><ul><li><strong>SSR 服务端翻译</strong>: <code>getServerTranslations()</code> 在 <code>getServerSideProps</code> 中预加载翻译</li><li><strong>Cookie 持久化</strong>: 语言偏好存储于 Cookie，通过 Next.js Middleware 自动检测 Referer 中的 <code>/en</code> 路径设置语言</li><li><strong>Ant Design 国际化</strong>: <code>ConfigProvider</code> 同步切换 <code>zhCN</code> / <code>enUS</code> 组件文案</li><li><strong>dayjs 语言包</strong>: 同步切换日期格式</li><li><strong>SEO 友好</strong>: 每个页面通过 <code>seoInfo</code> 属性设置多语言 title/description</li></ul><h3 id="_9-暗黑-浅色主题" tabindex="-1">9. 暗黑/浅色主题 <a class="header-anchor" href="#_9-暗黑-浅色主题" aria-label="Permalink to “9. 暗黑/浅色主题”">​</a></h3><p>通过 <code>ThemeContext</code> 实现全局主题切换：</p><ul><li>在 <code>&lt;html&gt;</code> 元素上设置 <code>data-theme</code> 属性（<code>light</code> / <code>dark</code>）</li><li>CSS 变量驱动全局颜色（背景、文字、边框、图表等）</li><li>Ant Design <code>ConfigProvider</code> 的 <code>theme.algorithm</code> 同步切换 <code>theme.defaultAlgorithm</code> / <code>theme.darkAlgorithm</code></li><li>交易页面（K 线图页面）同时更新 TradingView 图表主题</li><li>野持久化到 Cookie（key: <code>{ENV}-TRADE-THEME</code>）</li></ul><h3 id="_10-地区限制与合规" tabindex="-1">10. 地区限制与合规 <a class="header-anchor" href="#_10-地区限制与合规" aria-label="Permalink to “10. 地区限制与合规”">​</a></h3><p><code>RegionRestrictionProvider</code> 通过以下维度判断用户地区：</p><ol><li><strong>中国大陆 IP 检测</strong>: 内置 31 个中国省份 + 10 个 ISP 运营商的 IP 规则列表</li><li><strong>香港地区检测</strong>: 基于 IP 的香港地区判断</li><li><strong>功能限制</strong>: <ul><li>中国地区用户隐藏部分产品（如 <code>Price</code> 交易价格展示组件）</li><li><code>withRegionRestriction</code> HOC 包裹链接/按钮，阻止受限地区点击</li><li><code>RestrictedButton</code> / <code>RestrictedLink</code> 组件自动灰显受限功能</li><li><code>RegionRestrictionModal</code> 弹窗提示</li></ul></li></ol><h3 id="_11-http-请求层" tabindex="-1">11. HTTP 请求层 <a class="header-anchor" href="#_11-http-请求层" aria-label="Permalink to “11. HTTP 请求层”">​</a></h3><p><strong>请求架构</strong> (<code>request/</code> 目录):</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span>request/</span></span>
<span class="line"><span>├── server.js              # Axios 实例 + 请求拦截器</span></span>
<span class="line"><span>├── interceptorsResponse.js # 响应拦截器 + AES-CTR 解密</span></span>
<span class="line"><span>├── eventBus.js            # 全局事件总线（401 通知等）</span></span>
<span class="line"><span>├── api/</span></span>
<span class="line"><span>│   ├── user.js            # 用户相关 API</span></span>
<span class="line"><span>│   ├── spot.js            # 现货 API</span></span>
<span class="line"><span>│   ├── futures.js         # 期货 API</span></span>
<span class="line"><span>│   └── fc.js              # 合约 API</span></span>
<span class="line"><span>├── symbol.js              # 交易对信息 API</span></span>
<span class="line"><span>├── simulation.js          # 模拟账户 API</span></span>
<span class="line"><span>├── systemInfo.js          # 系统/浏览器指纹采集</span></span>
<span class="line"><span>├── finger.js              # 浏览器指纹（FingerprintJS）</span></span>
<span class="line"><span>└── jsencrypt.js           # RSA 加密</span></span></code></pre></div><p>关键特性：</p><ul><li><strong>请求去重</strong>: 通过 <code>pendingRequests</code> Map 自动取消重复请求</li><li><strong>AES-CTR 加密</strong>: 响应拦截器中使用 Web Crypto API 解密敏感数据</li><li><strong>Token 自动刷新</strong>: 401 时自动调用刷新接口，队列化等待中的请求，刷新成功后重放</li><li><strong>JWT 认证</strong>: 自动在请求头注入 <code>Authorization: Bearer {token}</code></li><li><strong>系统指纹</strong>: <code>printSystemInfo()</code> 采集浏览器/OS/设备信息附加到请求头</li><li><strong>Sentry 错误上报</strong>: 请求异常通过 <code>captureException</code> 上报</li></ul><h3 id="_12-监控与部署" tabindex="-1">12. 监控与部署 <a class="header-anchor" href="#_12-监控与部署" aria-label="Permalink to “12. 监控与部署”">​</a></h3><p><strong>Sentry 错误监控</strong>:</p><ul><li><code>sentry.server.config.js</code> - 服务端错误监控</li><li><code>sentry.edge.config.js</code> - Edge Runtime 监控</li><li><code>instrumentation.js</code> / <code>instrumentation-client.js</code> - 自动注入监控</li><li>手动上报点: WebSocket 异常、HTTP 请求失败、关键业务流程异常</li></ul><p><strong>PM2 多环境部署</strong> (<code>ecosystem.config.js</code>):</p><table tabindex="0"><thead><tr><th>环境</th><th>PM2 进程名</th><th>NEXT_PUBLIC_ENV</th><th>端口</th><th>用途</th></tr></thead><tbody><tr><td>本地</td><td><code>tradingSites-local</code></td><td><code>local</code></td><td>3000</td><td>本地开发调试</td></tr><tr><td>开发</td><td><code>tradingSites-dev</code></td><td><code>start</code></td><td>3000</td><td>开发联调</td></tr><tr><td>预发布</td><td><code>tradingSites-prv</code></td><td><code>prv</code></td><td>3000</td><td>预发布验证</td></tr><tr><td>生产</td><td><code>tradingSites-prd</code></td><td><code>prd</code></td><td>3000</td><td>生产环境</td></tr></tbody></table><p><strong>版本管理</strong>:</p><ul><li><code>generateBuildId()</code> 在 <code>next.config.js</code> 中生成唯一构建 ID（时间戳 + 随机字符 + Fisher-Yates 洗牌）</li><li><code>/api/version</code> 接口返回当前版本号</li><li>Cookie 存储版本号，检测版本更新后提示用户刷新</li></ul><p><strong>Next.js Middleware</strong>:</p><ul><li>语言检测：根据 Referer URL 自动设置语言 Cookie</li><li>Cache-Control 头设置：<code>no-cache, no-store, max-age=0, must-revalidate</code></li><li>静态资源路由排除：<code>/api</code>、<code>/_next/static</code>、<code>/_next/image</code> 等不经过中间件</li></ul><hr><h2 id="技能总结" tabindex="-1">技能总结 <a class="header-anchor" href="#技能总结" aria-label="Permalink to “技能总结”">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>具体技能点</th></tr></thead><tbody><tr><td>前端框架</td><td>Next.js 13 SSR/SSG、Pages Router、Middleware、getServerSideProps</td></tr><tr><td>React 生态</td><td>React 18、Hooks、Context API、useSyncExternalStore、自定义 Hooks</td></tr><tr><td>UI 工程化</td><td>Ant Design 5、Tailwind CSS、CSS-in-JS (@ant-design/cssinjs)、主题系统</td></tr><tr><td>数据可视化</td><td>TradingView Charting Library、ECharts 5、自研 DataFeed 适配层</td></tr><tr><td>实时通信</td><td>WebSocket 双通道架构、发布-订阅模式、重连机制、BroadcastChannel</td></tr><tr><td>国际化</td><td>next-i18next、SSR 翻译、Cookie 语言持久化、SEO 多语言</td></tr><tr><td>安全认证</td><td>JWT Token 管理、AES-CTR 加密/解密、RSA 加密、KYC/AML 流程</td></tr><tr><td>监控部署</td><td>Sentry 全链路监控、PM2 集群管理、Docker 容器化、多环境配置</td></tr><tr><td>工程化</td><td>ESLint、环境变量管理、Git 协作、代码规范</td></tr></tbody></table><hr><h2 id="项目挑战与解决方案" tabindex="-1">项目挑战与解决方案 <a class="header-anchor" href="#项目挑战与解决方案" aria-label="Permalink to “项目挑战与解决方案”">​</a></h2><ol><li><strong>高频行情数据渲染</strong> — 通过节流订阅机制 + <code>useSyncExternalStore</code> 避免不必要的重渲染，页面可见时断开 WebSocket 节省资源</li><li><strong>TradingView 多资产适配</strong> — 为现货/期货/股票/期权分别实现 DataFeed 适配层，统一实时数据脉冲注入接口</li><li><strong>Token 无感刷新</strong> — 响应拦截器中实现 401 请求队列化，刷新完成后批量重放，用户无感知</li><li><strong>跨国合规要求</strong> — 基于 IP 规则引擎 + HOC 组件包装实现功能级别的地区可见性控制</li><li><strong>暗黑主题兼容</strong> — 同时适配 Ant Design、TradingView、ECharts 三套组件体系的主题联动</li></ol>`,87)])])}const u=e(d,[["render",o]]);export{b as __pageData,u as default};
